css:
.s7-screen,.s7-screen *{box-sizing:border-box;}
.s7-screen{position:relative;width:390px;height:844px;overflow:hidden;background:#090c14;font-family:'Satoshi',system-ui,-apple-system,'Segoe UI',sans-serif;color:#e8eaf0;-webkit-font-smoothing:antialiased;}
.s7-glow{position:absolute;top:-150px;left:10px;width:360px;height:300px;border-radius:50%;filter:blur(26px);pointer-events:none;background:radial-gradient(closest-side,rgba(45,212,191,0.13),transparent 70%);z-index:0;}

.s7-header{position:relative;z-index:40;display:flex;align-items:center;gap:16px;padding:16px 24px;background:rgba(9,12,20,0.8);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid rgba(255,255,255,0.06);}
.s7-back{display:flex;align-items:center;justify-content:center;padding:8px;margin-left:-8px;border-radius:20px;color:#7e8a9e;}
.s7-h1{margin:0;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:24px;line-height:1.15;color:#e8eaf0;}

.s7-main{position:relative;z-index:1;padding:32px 24px;}
.s7-upload{display:flex;align-items:center;gap:12px;width:100%;padding:16px;border-radius:32px;text-align:left;background:rgba(45,212,191,0.08);border:1px solid rgba(45,212,191,0.2);}
.s7-uploadicon{flex:0 0 auto;width:40px;height:40px;border-radius:26px;display:flex;align-items:center;justify-content:center;background:rgba(45,212,191,0.14);}
.s7-uploadtext{flex:1;min-width:0;}
.s7-uploadtitle{margin:0;font-size:14px;font-weight:600;color:#e8eaf0;letter-spacing:-0.005em;line-height:1.3;}
.s7-uploadsub{margin:2px 0 0;font-size:11.5px;line-height:1.45;color:#7e8a9e;}

/* modal: fixed inset-0 in the app; absolute here so it stays inside the frame */
.s7-scrim{position:absolute;inset:0;z-index:100;background:rgba(4,8,14,0.82);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);}

.s7-sheet{position:absolute;z-index:101;left:0;right:0;bottom:0;padding:24px;border-radius:24px 24px 0 0;background:#0d111b;border:1px solid rgba(255,255,255,0.1);border-bottom:0;}
.s7-sheethead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:4px;}
.s7-sheettitle{margin:0;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:20px;line-height:1.2;color:#e8eaf0;}
.s7-close{display:flex;align-items:center;justify-content:center;color:#7e8a9e;}

.s7-file{display:flex;align-items:center;gap:12px;margin-top:16px;padding:14px;border-radius:26px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);}
.s7-fileicon{flex:0 0 auto;width:36px;height:36px;border-radius:20px;display:flex;align-items:center;justify-content:center;background:rgba(45,212,191,0.12);}
.s7-filetext{flex:1;min-width:0;}
.s7-filename{margin:0;font-size:13px;font-weight:600;line-height:1.3;color:#e8eaf0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.s7-filemeta{margin:2px 0 0;font-size:11px;line-height:1.4;color:#7e8a9e;font-variant-numeric:tabular-nums;}

.s7-progress{display:flex;align-items:center;gap:10px;margin-top:16px;}
.s7-spin{display:flex;align-items:center;justify-content:center;transform:rotate(115deg);}
.s7-status{font-size:13.5px;line-height:1.4;color:#a9b2c1;font-variant-numeric:tabular-nums;}
.s7-track{position:relative;height:4px;margin-top:10px;border-radius:9999px;background:rgba(255,255,255,0.06);overflow:hidden;}
.s7-bar{position:absolute;left:0;top:0;bottom:0;width:66%;border-radius:9999px;background:linear-gradient(90deg,rgba(45,212,191,0.55),#2dd4bf);}

.s7-raw{margin-top:16px;padding:12px 10px 11px;border-radius:26px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.05);}
.s7-rawlabel{margin:0 0 7px 6px;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:0.14em;color:#5a6578;line-height:1.3;}
.s7-rawline{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:3px 8px;border-radius:8px;font-family:ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:10.5px;line-height:1.65;color:#5a6578;white-space:nowrap;overflow:hidden;}
.s7-hit{background:rgba(45,212,191,0.07);box-shadow:inset 2px 0 0 #2dd4bf;color:#a9b2c1;}
.s7-rawtext{overflow:hidden;text-overflow:ellipsis;}
.s7-tag{flex:0 0 auto;font-family:'Satoshi',system-ui,sans-serif;font-size:10px;font-weight:600;letter-spacing:0.04em;color:#2dd4bf;}
.s7-caret{display:inline-block;width:5px;height:11px;margin-left:1px;vertical-align:-1px;background:rgba(45,212,191,0.8);border-radius:1px;}

.s7-panel{margin:18px 0 8px 2px;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:0.14em;color:#7e8a9e;line-height:1.3;}
.s7-rows{display:flex;flex-direction:column;gap:10px;}
.s7-row{display:flex;align-items:flex-start;gap:10px;padding:13px 14px;border-radius:26px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.05);}
.s7-rowicon{flex:0 0 auto;display:flex;align-items:center;justify-content:center;margin-top:1px;}
.s7-rowtext{flex:1;min-width:0;}
.s7-rowtitle{margin:0;font-size:13px;font-weight:600;line-height:1.35;color:#e8eaf0;}
.s7-rowsub{margin:3px 0 0;font-size:11px;line-height:1.45;color:#7e8a9e;}

.s7-rowlab{display:block;}
.s7-labtop{display:flex;align-items:center;gap:8px;}
.s7-name{flex:1;min-width:0;font-size:14px;font-weight:500;color:#e8eaf0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.s7-val{font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-size:20px;line-height:1;color:#e8eaf0;font-variant-numeric:tabular-nums;}
.s7-unit{font-size:10.5px;color:#7e8a9e;}
.s7-labsub{margin:6px 0 0;font-size:10.5px;line-height:1.45;color:#5a6578;font-variant-numeric:tabular-nums;}

.s7-note{margin:14px 0 0;font-size:10.5px;line-height:1.5;color:#5a6578;}

.s7-privacy{display:flex;align-items:flex-start;gap:8px;margin-top:14px;}
.s7-shield{flex:0 0 auto;margin-top:2px;}
.s7-privacytext{margin:0;font-size:11.5px;line-height:1.5;color:#7e8a9e;}

.s8-frame{position:relative;width:390px;height:844px;overflow:hidden;background:#090c14;font-family:'Satoshi',system-ui,-apple-system,'Segoe UI',sans-serif;-webkit-font-smoothing:antialiased;color:#e8eaf0;}
.s8-glow{position:absolute;top:-150px;left:10px;width:360px;height:300px;border-radius:50%;filter:blur(26px);pointer-events:none;background:radial-gradient(closest-side,rgba(45,212,191,0.13),transparent 70%);z-index:0;}

.s8-header{position:relative;z-index:3;padding:11px 20px;background:rgba(9,12,20,0.8);backdrop-filter:blur(20px);border-bottom:1px solid rgba(255,255,255,0.06);}
.s8-headRow{display:flex;align-items:center;gap:14px;}
.s8-back{display:flex;align-items:center;justify-content:center;width:20px;height:20px;color:#7e8a9e;flex:none;}
.s8-title{margin:0;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:22px;line-height:28px;color:#e8eaf0;}

.s8-main{position:relative;z-index:1;padding:8px 20px 0;}
.s8-card{padding:12px;border-radius:20px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);}
.s8-cardTop{display:flex;align-items:center;justify-content:space-between;margin-bottom:2px;}
.s8-cardTitle{margin:0;font-size:14.5px;font-weight:600;line-height:19px;color:#e8eaf0;}
.s8-cardDate{font-size:11px;line-height:19px;color:#7e8a9e;}
.s8-flagNote{margin:0 0 4px;font-size:11.5px;line-height:14.5px;color:#f59e0b;}
.s8-egNote{margin:0 0 7px;font-size:10.5px;line-height:14px;color:#7e8a9e;padding-left:8px;border-left:2px solid rgba(255,255,255,0.10);}

.s8-panels{display:flex;flex-direction:column;gap:7px;}
.s8-panelLabel{margin:0 0 4px 2px;font-size:10px;line-height:12px;font-weight:600;letter-spacing:0.14em;text-transform:uppercase;color:#7e8a9e;}
.s8-rows{display:flex;flex-direction:column;gap:4px;}

.s8-marker{padding:4px 10px;border-radius:12px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.05);}
.s8-mHead{display:flex;align-items:center;gap:6px;}
.s8-mName{flex:1 1 auto;min-width:0;font-size:12.5px;line-height:18px;font-weight:500;color:#e8eaf0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.s8-mValue{flex:none;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-size:17px;line-height:19px;color:#e8eaf0;font-variant-numeric:tabular-nums;}
.s8-mUnit{flex:none;font-size:10px;line-height:19px;color:#7e8a9e;}

.s8-bar{position:relative;height:7px;border-radius:999px;background:rgba(255,255,255,0.06);margin-top:4px;}
.s8-band{position:absolute;top:0;bottom:0;border-radius:999px;background:rgba(52,211,153,0.22);border:1px solid rgba(52,211,153,0.25);}
.s8-dot{position:absolute;top:50%;width:10px;height:10px;margin-top:-5px;margin-left:-5px;border-radius:50%;background:#0d111b;border:2.5px solid #2dd4bf;}
.s8-dotOut{border-color:#f59e0b;}

.s8-scale{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-top:5px;min-height:12px;}
.s8-scaleEnd{font-size:10px;line-height:12px;color:#5a6578;font-variant-numeric:tabular-nums;flex:none;}
.s8-scaleMid{font-size:10px;line-height:12px;color:#5a6578;}
.s8-badge{font-size:10px;line-height:11px;font-weight:600;padding:1.5px 7px;border-radius:999px;color:#f59e0b;background:rgba(245,158,11,0.12);border:1px solid rgba(245,158,11,0.28);white-space:nowrap;}

.s8-foot{margin:8px 0 0;font-size:10.5px;line-height:13.5px;color:#5a6578;}

.s8-nav{position:absolute;z-index:5;bottom:24px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:9px 30px;border-radius:999px;background:rgba(9,12,20,0.75);border:1px solid rgba(255,255,255,0.10);box-shadow:0 8px 32px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255,255,255,0.12);backdrop-filter:blur(28px) saturate(180%);}
.s8-navBtn{position:relative;display:flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:50%;color:rgba(255,255,255,0.40);}
.s8-navBtnOn{color:#2dd4bf;background:rgba(45,212,191,0.15);}

.s9-root{position:relative;width:390px;height:844px;overflow:hidden;background:#090c14;color:#e8eaf0;font-family:'Satoshi',system-ui,-apple-system,sans-serif;-webkit-font-smoothing:antialiased;}
.s9-glow{position:absolute;top:-150px;left:10px;width:360px;height:300px;border-radius:50%;filter:blur(26px);pointer-events:none;background:radial-gradient(closest-side,rgba(45,212,191,0.13),transparent 70%);}
.s9-header{position:relative;z-index:2;display:flex;align-items:center;gap:16px;padding:16px 24px;background:rgba(9,12,20,0.8);border-bottom:1px solid rgba(255,255,255,0.06);}
.s9-back{display:flex;align-items:center;justify-content:center;margin-left:-8px;padding:8px;color:#7e8a9e;}
.s9-title{margin:0;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-weight:400;font-size:24px;line-height:32px;color:#e8eaf0;}
.s9-main{position:relative;z-index:1;padding:24px 24px 0;}
.s9-example{margin:0 0 18px;font-size:11px;line-height:15px;color:#5a6578;}
.s9-card{background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);border-radius:16px;padding:24px;}
.s9-card-b{background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);border-radius:16px;padding:20px;margin-top:16px;}
.s9-h3{display:flex;align-items:center;gap:8px;margin:0 0 10px;font-size:15px;font-weight:600;line-height:20px;color:#e8eaf0;}
.s9-h3ic{flex:none;width:16px;height:16px;color:#2dd4bf;}
.s9-pills{display:flex;align-items:center;gap:6px;overflow:hidden;margin:0 0 12px;padding-bottom:2px;}
.s9-pill{flex:none;padding:4px 12px;border-radius:9999px;font-size:12px;font-weight:500;line-height:18px;white-space:nowrap;background:rgba(255,255,255,0.05);color:#c9cdd5;}
.s9-pill-on{flex:none;padding:4px 12px;border-radius:9999px;font-size:12px;font-weight:500;line-height:18px;white-space:nowrap;background:#2dd4bf;color:#04121a;}
.s9-chart{display:block;width:294px;height:148px;}
.s9-cval{font-family:'Satoshi',system-ui,sans-serif;font-size:10px;fill:#a9b2c1;font-variant-numeric:tabular-nums;}
.s9-cdate{font-family:'Satoshi',system-ui,sans-serif;font-size:10px;fill:#5a6578;}
.s9-cedge{font-family:'Satoshi',system-ui,sans-serif;font-size:10px;fill:#5a6578;font-variant-numeric:tabular-nums;}
.s9-cband{font-family:'Satoshi',system-ui,sans-serif;font-size:10px;fill:#5a6578;}
.s9-foot{display:flex;align-items:center;justify-content:space-between;margin-top:8px;padding:0 2px;}
.s9-foot-l{font-size:11px;line-height:15px;color:#5a6578;}
.s9-foot-r{font-size:11px;line-height:15px;color:#7e8a9e;font-variant-numeric:tabular-nums;}
.s9-note{margin:8px 0 0;font-size:11px;line-height:15px;color:#5a6578;}
.s9-tbl{display:grid;grid-template-columns:1fr 50px 50px 50px;align-items:center;}
.s9-th{padding:0 2px 8px 0;font-size:10px;line-height:14px;color:#5a6578;text-align:right;}
.s9-th-x{padding:0 0 8px 0;}
.s9-name{padding:8px 8px 8px 0;border-top:1px solid rgba(255,255,255,0.05);}
.s9-nm{display:flex;align-items:center;gap:6px;font-size:13.5px;line-height:18px;color:#e8eaf0;}
.s9-dot{flex:none;width:6px;height:6px;border-radius:50%;background:#f59e0b;}
.s9-sub{margin-top:1px;font-size:10.5px;line-height:14px;color:#5a6578;}
.s9-td{padding:8px 2px 8px 0;border-top:1px solid rgba(255,255,255,0.05);text-align:right;font-family:'Instrument Serif',Georgia,serif;font-style:italic;font-size:18px;line-height:22px;color:#e8eaf0;font-variant-numeric:tabular-nums;}
.s9-flag{display:flex;gap:6px;margin:10px 0 0;font-size:10.5px;line-height:14px;color:#f59e0b;}
.s9-flagdot{flex:none;width:6px;height:6px;margin-top:4px;border-radius:50%;background:#f59e0b;}
.s9-tnote{margin:10px 0 0;font-size:10.5px;line-height:14px;color:#5a6578;}
.s9-nav{position:absolute;left:50%;bottom:24px;transform:translateX(-50%);padding:10px 32px;border-radius:9999px;background:rgba(9,12,20,0.75);border:1px solid rgba(255,255,255,0.10);box-shadow:0 8px 32px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255,255,255,0.12);z-index:3;}
.s9-navrow{position:relative;display:flex;align-items:center;gap:8px;}
.s9-navsel{position:absolute;left:0;top:50%;margin-top:-20px;width:40px;height:40px;border-radius:50%;background:rgba(45,212,191,0.15);}
.s9-tab{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;color:rgba(255,255,255,0.40);}
.s9-tab-on{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;color:#2dd4bf;}

.s11-screen {
  position: relative;
  width: 390px;
  height: 844px;
  overflow: hidden;
  background: #090c14;
  color: #e8eaf0;
  font-family: 'Satoshi', system-ui, -apple-system, 'Helvetica Neue', sans-serif;
  -webkit-font-smoothing: antialiased;
  box-sizing: border-box;
}
.s11-screen *, .s11-screen *::before, .s11-screen *::after { box-sizing: border-box; }

.s11-glow {
  position: absolute;
  top: -150px;
  left: 20px;
  width: 340px;
  height: 300px;
  border-radius: 50%;
  filter: blur(26px);
  background: radial-gradient(closest-side, rgba(45, 212, 191, 0.13), transparent 70%);
  pointer-events: none;
  z-index: 0;
}

/* ---------- header ---------- */
.s11-header {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 15px 20px 14px;
  background: rgba(9, 12, 20, 0.8);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.s11-back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  color: #7e8a9e;
  flex: 0 0 auto;
}
.s11-back svg { width: 20px; height: 20px; }
.s11-headtext { min-width: 0; }
.s11-title {
  margin: 0;
  font-family: 'Instrument Serif', Georgia, serif;
  font-style: italic;
  font-weight: 400;
  font-size: 23px;
  line-height: 1.15;
  color: #e8eaf0;
}
.s11-subtitle {
  margin: 3px 0 0;
  font-size: 11.5px;
  line-height: 1.2;
  color: #7e8a9e;
  letter-spacing: 0.01em;
}

/* ---------- main ---------- */
.s11-main {
  position: relative;
  z-index: 1;
  padding: 18px 20px 0;
}

/* reviewed status */
.s11-status {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 14px;
  background: rgba(45, 212, 191, 0.08);
  border: 1px solid rgba(45, 212, 191, 0.22);
}
.s11-status-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 999px;
  background: rgba(45, 212, 191, 0.16);
  color: #2dd4bf;
  flex: 0 0 auto;
}
.s11-status-icon svg { width: 12px; height: 12px; }
.s11-status-text {
  font-size: 12.5px;
  line-height: 1.35;
  color: #c9cdd5;
}

/* week over week */
.s11-eyebrow {
  margin: 0 0 11px;
  font-size: 10.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: #7e8a9e;
}
.s11-deltas { margin-top: 22px; }
.s11-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
}
.s11-row + .s11-row { margin-top: 8px; }
.s11-row-label {
  font-size: 13.5px;
  color: #e8eaf0;
}
.s11-row-right {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.s11-row-value {
  font-size: 13.5px;
  font-weight: 600;
  color: #2dd4bf;
  font-variant-numeric: tabular-nums;
}
.s11-chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  min-width: 62px;
  justify-content: flex-end;
}
.s11-arrow { width: 12px; height: 12px; flex: 0 0 auto; }
.s11-better { color: #34d399; }
.s11-worse  { color: #f59e0b; }
.s11-flat   { color: #7e8a9e; font-weight: 500; }

/* the quiet, always-visible provenance line */
.s11-disclaimer {
  margin: 16px 0 0;
  padding-left: 11px;
  border-left: 2px solid rgba(255, 255, 255, 0.10);
  font-size: 11.5px;
  line-height: 1.55;
  color: #7e8a9e;
}

/* coach note */
.s11-notes { margin-top: 22px; }
.s11-card {
  position: relative;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(45, 212, 191, 0.15);
  border-radius: 26px;
  padding: 20px 20px 18px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.14), 0 28px 70px rgba(0, 0, 0, 0.35), 0 4px 20px rgba(45, 212, 191, 0.08);
}
.s11-specular {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.12), transparent);
  pointer-events: none;
}
.s11-tint {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(45, 212, 191, 0.05) 0%, transparent 55%);
  pointer-events: none;
}
